const commands = {
  balance: (ledgerPath) => {
    const entries = parse(fs.readFileSync(ledgerPath, 'utf8'));
    console.log(entries.reduce((total, entry) => total + entry.amountCents, 0) / 100);
  },
  report: (ledgerPath) => {
    const entries = parse(fs.readFileSync(ledgerPath, 'utf8'));
    entries.sort((a, b) => a.date.localeCompare(b.date)).forEach(entry => {
      console.log(`${entry.date} ${entry.amountCents / 100}`);
    });
  },
  monthly: (ledgerPath) => {
    const entries = parse(fs.readFileSync(ledgerPath, 'utf8'));
    console.log(renderMonthly(groupByMonth(entries)));
  }
};

if (process.argv.length < 3) {
  console.log('Usage: node cli.js [balance|report|monthly] <ledger.csv>');
  process.exit(1);
}

const commandName = process.argv[2];
const ledgerPath = process.argv[3];

if (!commands[commandName]) {
  console.log(`Unknown command: ${commandName}`);
  console.log('Please specify a known command: balance, report, or monthly.');
  process.exit(1);
}

